CREATE     PROCEDURE [synapse_fo].[usp_Update_ECORESPRODUCT]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:39
	Description: Update stored procedure for ECORESPRODUCT from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DISPLAYPRODUCTNUMBER] = stg.[DISPLAYPRODUCTNUMBER],
		tgt.[ENGCHGPRODUCTCATEGORYDETAILS] = stg.[ENGCHGPRODUCTCATEGORYDETAILS],
		tgt.[ENGCHGPRODUCTOWNERID] = stg.[ENGCHGPRODUCTOWNERID],
		tgt.[ENGCHGPRODUCTREADINESSPOLICY] = stg.[ENGCHGPRODUCTREADINESSPOLICY],
		tgt.[ENGCHGPRODUCTRELEASEPOLICY] = stg.[ENGCHGPRODUCTRELEASEPOLICY],
		--tgt.[FileName] = stg.[FileName],
		tgt.[INSTANCERELATIONTYPE] = stg.[INSTANCERELATIONTYPE],
		--tgt.[ISPRODUCTVARIANTUNITCONVERSIONENABLED] = stg.[ISPRODUCTVARIANTUNITCONVERSIONENABLED],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		--tgt.[LSN] = stg.[LSN],
		tgt.[MODIFIEDBY] = stg.[MODIFIEDBY],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[PDSCWPRODUCT] = stg.[PDSCWPRODUCT],
		--tgt.[PRODUCTMASTER] = stg.[PRODUCTMASTER],
		tgt.[PRODUCTTYPE] = stg.[PRODUCTTYPE],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		--tgt.[RELATIONTYPE] = stg.[RELATIONTYPE],
		--tgt.[RETAILCOLORGROUPID] = stg.[RETAILCOLORGROUPID],
		--tgt.[RETAILSIZEGROUPID] = stg.[RETAILSIZEGROUPID],
		--tgt.[RETAILSTYLEGROUPID] = stg.[RETAILSTYLEGROUPID],
		--tgt.[RETAITOTALWEIGHT] = stg.[RETAITOTALWEIGHT],
		--tgt.[RICSPRODPRICECALC] = stg.[RICSPRODPRICECALC],
		tgt.[SEARCHNAME] = stg.[SEARCHNAME],
		tgt.[SERVICETYPE] = stg.[SERVICETYPE]
		--tgt.[SysRowId] = stg.[SysRowId],
		--tgt.[VARIANTCONFIGURATIONTECHNOLOGY] = stg.[VARIANTCONFIGURATIONTECHNOLOGY]
	 FROM [synapse_fo].[ECORESPRODUCT] tgt
		INNER JOIN [staging_fo].[ECORESPRODUCT] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
